def _best_paragraph(content, keywords):
    parts = re.split(r"\n\s*\n", content)
    best, best_score = parts[0], -1
    for p in parts:
        score = sum(1 for k in keywords
                if k.lower() in p.lower())
        if score > best_score:
            best, best_score = p, score

